update iot_push_transform_rule
set status = 0,
    update_by = #{updateBy},
    update_time = now()
where app_unique_id = #{appUniqueId}
  and scope_type = #{scopeType}
  and status = 1
  and deleted = 0


      and product_key = #{productKey}


      and (product_key is null or product_key = '')



    and id != #{excludeId}

update iot_push_transform_rule
set deleted = 1, status = 2, update_by = #{updateBy}, update_time = now()
where app_unique_id = #{appUniqueId} and deleted = 0 and id != #{keepId}
